import{_ as t,o,c as i,a3 as a}from"./chunks/framework.CRbjHCyB.js";const p=JSON.parse('{"title":"Query","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Query | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/clice/cli/query"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/clice/cli/query"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/cli/query"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/cli/query"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/cli/query"}]]},"headers":[],"relativePath":"clice/cli/query.md","filePath":"en/clice/cli/query.md","lastUpdated":1789769625000}'),s={name:"clice/cli/query.md"};function n(r,e,d,l,c,h){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="query" tabindex="-1">Query <a class="header-anchor" href="#query" aria-label="Permalink to &quot;Query&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p><code>clice query</code> asks the persisted index a structured question and prints the answer as JSON on stdout — for scripts and coding agents that want the facts a language server has without speaking LSP. It reads the index straight from disk, the same index <code>clice index</code> builds and an editor session keeps up to date, so it works while the editor is open and needs no server when it is not.</p><p><strong>Usage</strong>: <code>clice query --method &lt;question&gt; [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;] [--fresh] [question options]</code></p><h2 id="questions" tabindex="-1">Questions <a class="header-anchor" href="#questions" aria-label="Permalink to &quot;Questions&quot;">​</a></h2><ul><li><code>symbolSearch --query &lt;text&gt; [--limit &lt;n&gt;] [--kind &lt;Kind,...&gt;]</code> lists the symbols whose name contains the text, best matches first, with their kind, file, line and id.</li><li><code>definition</code>, <code>readSymbol</code>, <code>references [--include-declaration]</code>, <code>callGraph [--direction callers|callees|both]</code> and <code>typeHierarchy [--direction supertypes|subtypes|both]</code> answer about one symbol, named by <code>--name &lt;name&gt;</code> (optionally narrowed with <code>--path</code>), by <code>--symbol &lt;id&gt;</code> (the <code>#&lt;hex&gt;</code> id an earlier answer carried) or by <code>--path &lt;file&gt; --line &lt;n&gt;</code> (the symbol defined on that line). An ambiguous name lists the candidates&#39; count and asks for an id.</li><li><code>documentSymbols --path &lt;file&gt;</code> is the file&#39;s outline.</li><li><code>compileCommand --path &lt;file&gt;</code> is the command the editor would compile the file with, and where it came from: the file&#39;s own database entry, a host source for a header, a rule&#39;s default command, a command inferred from a nearby unit, or the fallback.</li><li><code>projectFiles [--filter all|source|header|module]</code> lists the build&#39;s files; <code>fileDeps --path &lt;file&gt; [--direction includes|includers|both] [--depth &lt;n&gt;]</code> and <code>impactAnalysis --path &lt;file&gt;</code> follow the include graph.</li></ul><p>Paths are workspace-relative or absolute in questions, absolute in answers; lines are 1-based.</p><h2 id="answers" tabindex="-1">Answers <a class="header-anchor" href="#answers" aria-label="Permalink to &quot;Answers&quot;">​</a></h2><p>Every answer is one JSON object: <code>{&quot;result&quot;: ..., &quot;stale&quot;: [...]}</code> on success, <code>{&quot;error&quot;: &quot;...&quot;, &quot;stale&quot;: [...]}</code> with exit code 1 when the question cannot be answered (an unknown symbol, a file that does not exist, an invalid option).</p><p><code>stale</code> lists the files whose rows the answer had to leave out because their content on disk no longer matches what was indexed — the positions the index holds for them would point into text that moved. A file that changed only because a header it includes changed keeps answering from its last rows. A symbol whose definition sits in a stale file is reported as not found, with the file named, so a reader can tell &quot;does not exist&quot; from &quot;not indexed yet&quot;. Only files the answer consulted are checked: a symbol added to a file after it was indexed is simply absent, since no row leads to that file — <code>--fresh</code> is the way to ask about the current disk. The index never sees unsaved editor buffers: the disk is the truth it describes.</p><p><code>--fresh</code> brings the index up to date with the disk before answering: while an editor session has the workspace open, its server runs the sweep; otherwise the command runs the indexer itself, building the index from nothing when there is none yet. Either way only the units whose inputs changed are recompiled. Without <code>--fresh</code> a workspace with no index answers with an error.</p>',11)])])}const f=t(s,[["render",n]]);export{p as __pageData,f as default};
